d['validation']={'backend':['go test ./...','go test -race ./...','go vet ./...'],'frontend':['npm test -- --maxWorkers=2 (423/423)','npm run lint','npm run build'],'e2e':['rf-budget.spec.js with fresh real backend','network-deadline.spec.js with separate fresh real backend; existing golden response SHA256 retained'],'final_checks':['docs reference-page build','docs/validate_docs.py: 48 HTML pages, 41 API paths','scripts/versioning.py check: 0.11.0','git diff --check'], 'unit_tests':'CPU/memory discovery, v1/v2/hybrid/deep visible ancestors, fractional quota, cpusets, malformed/unreadable/absent, sentinel semantics, immutability, fingerprint dynamics and fixed-policy invariance','calibration':'64 actual-container workflow/frequency/profile rows; HTTP, concurrency, cancellation, uncached async overlap; profile constraints compared with external Docker inspect','notes':['combined real E2Es initially shared one budget and failed; separate fresh backend runs pass','frontend full parallel run under build/test contention timed out; bounded-worker rerun passes without changing tests','Python docs validator requires PyYAML; installed only into a disposable /tmp docs venv','existing Vite chunk-size and pandoc mathml deprecation warnings persist']}
